Component({selector: 'app-root',template: `
    <div>
      <h1>How I feel about Angular</h1>
      <article>
        <p>
          Angular is my favorite framework, and this is why. Angular has the coolest deferrable view
          feature that makes defer loading content the easiest and most ergonomic it could possibly
          be.
        </p>
      </article>

      @defer {
        <article-comments />
      } @placeholder (minimum 1s) {
        <p>Placeholder for comments</p>
      } @loading (minimum 1s; after 500ms) {
        <p>Loading comments...</p>
      } @error {
        <p>Failed to load comments</p>
      }
    </div>
  `,imports:[ArticleComments],})

function noControlsError(isFormGroup: boolean): string { return `
    There are no form controls registered with this ${
      isFormGroup ? 'group' : 'array'
    } yet. If you're using ngModel,
    you may want to check next tick (e.g. use setTimeout).
  `; }

function createBarText(bar: BargraphNode) { return `${bar.label} | ${bar.value.toFixed(1)} ms | ${bar.count} ${
    bar.count === 1 ? 'instance' : 'instances'
  }`; }
